// Native assets are kept separate from Ember projects: their graphs stay in Unreal.
(()=>{
 const bar=document.createElement('nav');bar.className='editor-navigation';bar.setAttribute('aria-label','Editor workspace');bar.innerHTML='<button id="builder-workspace" class="selected">Particle builder</button><button id="niagara-workspace">Project Niagara systems</button><span>Build simply. Go deeper when you need to.</span>';document.querySelector('header').after(bar);
 const panel=document.createElement('section');panel.id='native-workspace';panel.hidden=true;panel.innerHTML='<aside class="native-library"><div class="eyebrow">CONNECTED PROJECT</div><h2>Niagara systems</h2><p>Work with native effects while preserving their emitters, modules, and graphs.</p><button id="scan-niagara" class="primary">Read project effects</button><input id="native-search" placeholder="Find a system…" aria-label="Find Niagara system"><div id="native-assets"></div></aside><section class="native-details"><div class="eyebrow">SYSTEM OVERVIEW</div><h1 id="native-title">Your advanced effects workspace</h1><p id="native-path"></p><p id="native-status" role="status">Connect an Unreal project, then read its effects. Save and close Unreal before reading or saving a copy.</p><div id="native-summary"></div><div class="native-capabilities"><h2>Go beyond the particle builder</h2><p>GPU particles, ribbons, lights, skeletal sampling, scene collisions, event handlers, simulation stages, data interfaces, and custom scripts stay in the native system. Run and preview them in Unreal.</p><button id="native-guide">How this workspace works</button></div></section><aside class="native-controls"><div class="eyebrow">FRIENDLY CONTROLS</div><h2>Exposed properties</h2><p>These are controls the effect author chose to expose. Advanced types remain in Unreal.</p><div id="native-parameters"></div><label>New copy name<input id="native-copy-name" maxlength="80" value="My_Effect"></label><button id="copy-niagara" class="primary" disabled>Save a new system</button><button id="open-native-editor" disabled>Open full editor & preview</button><small>Original systems stay unchanged. Copies save under Content/Ember/Systems.</small></aside>';bar.after(panel);
 let systems=[],selected=null,busy=false,values={},project=null;
 const status=text=>document.querySelector('#native-status').textContent=text;
 function setBusy(value){busy=value;document.querySelector('#scan-niagara').disabled=value;document.querySelector('#copy-niagara').disabled=value||!selected;document.querySelector('#open-native-editor').disabled=value||!selected;document.querySelectorAll('#native-assets button,#native-parameters input').forEach(el=>el.disabled=value);}
 function showNative(value){document.querySelector('main').hidden=value;panel.hidden=!value;document.querySelector('#builder-workspace').classList.toggle('selected',!value);document.querySelector('#niagara-workspace').classList.toggle('selected',value);}
 document.querySelector('#builder-workspace').onclick=()=>showNative(false);document.querySelector('#niagara-workspace').onclick=()=>showNative(true);
 function renderAssets(){const list=document.querySelector('#native-assets');list.replaceChildren();const query=document.querySelector('#native-search').value.toLowerCase();for(const system of systems.filter(s=>(s.name+' '+s.asset).toLowerCase().includes(query))){const button=document.createElement('button');button.textContent=system.name;button.title=system.asset;button.className=selected?.asset===system.asset?'selected':'';button.disabled=busy;button.onclick=()=>run({action:'inspect',asset:system.asset});list.append(button);}if(!systems.length){const text=document.createElement('p');text.textContent='No systems loaded yet.';list.append(text);}}
 document.querySelector('#native-search').oninput=renderAssets;
 function describe(system){selected=system;values={};document.querySelector('#native-title').textContent=system.name;document.querySelector('#native-path').textContent=system.asset;document.querySelector('#native-copy-name').value=(system.name+'_Edited').slice(0,80);const summary=document.querySelector('#native-summary');summary.replaceChildren();for(const emitter of system.emitters){const card=document.createElement('article'),title=document.createElement('h3'),body=document.createElement('p');title.textContent=emitter.name;body.textContent=emitter.simulation+' simulation · '+(emitter.enabled?'Enabled':'Disabled')+' · '+emitter.renderers.map(r=>r.replace('Niagara','').replace('RendererProperties','')).join(', ');card.append(title,body);summary.append(card);}const controls=document.querySelector('#native-parameters');controls.replaceChildren();for(const p of system.parameters){const label=document.createElement('label');label.append(document.createTextNode(p.name.replace(/^User\./,'').replace(/([a-z])([A-Z])/g,'$1 $2')));if(p.type==='advanced'){const note=document.createElement('small');note.textContent=p.nativeType+' — edit in full editor';label.append(note);}else{values[p.name]=structuredClone(p.value);const components=Array.isArray(p.value)?p.value:[p.value];const group=document.createElement('div');group.className='native-value';components.forEach((v,index)=>{const input=document.createElement('input');input.setAttribute('aria-label',p.name+(components.length>1?' '+['X / R','Y / G','Z / B','Alpha'][index]:''));input.type=p.type==='boolean'?'checkbox':'number';if(input.type==='checkbox')input.checked=v;else{input.value=v;input.step=p.type==='integer'?'1':'any';input.min=p.type==='integer'?'-2147483648':'-1000000000';input.max=p.type==='integer'?'2147483647':'1000000000';}input.oninput=()=>{const value=input.type==='checkbox'?input.checked:input.valueAsNumber;if(components.length>1)values[p.name][index]=value;else values[p.name]=value;};group.append(input);});label.append(group);}controls.append(label);}if(!system.parameters.length){const note=document.createElement('p');note.textContent='This system has no exposed controls. Open the full editor to add User Parameters or edit its modules.';controls.append(note);}renderAssets();}
 async function run(request){if(busy)return;if(!native?.niagaraWorkspace){status('Use the installed Ember desktop app for the native editor.');return;}setBusy(true);status('Working with Unreal… Large projects can take a few minutes.');try{const reply=await native.niagaraWorkspace({...request,project});if(!reply.ok)throw Error(reply.error);if(reply.canceled){status('Canceled. Your effect and controls are unchanged.');return;}if(request.action==='list'){project=reply.project;selected=null;document.querySelector('#native-parameters').replaceChildren();document.querySelector('#native-summary').replaceChildren();document.querySelector('#native-title').textContent='Choose a Niagara system';document.querySelector('#native-path').textContent='';systems=reply.result.systems.sort((a,b)=>a.name.localeCompare(b.name));renderAssets();status(systems.length+' systems found. Select one to see its emitters and controls.');}else{describe(reply.result);if(request.action==='copy'){systems.push({name:selected.name,asset:selected.asset});renderAssets();status('Saved '+selected.name+'. Open the full editor to preview it.');}else status('Native system loaded. Change its exposed controls, then save a new system.');}}catch(error){status(error.message);}finally{setBusy(false);}}
 document.querySelector('#scan-niagara').onclick=()=>run({action:'list'});
 document.querySelector('#copy-niagara').onclick=()=>{const inputs=[...document.querySelectorAll('#native-parameters input')];if(inputs.some(i=>!i.checkValidity()||(i.type==='number'&&!Number.isFinite(i.valueAsNumber)))){status('Enter valid numbers for each exposed control.');return;}run({action:'copy',asset:selected.asset,name:document.querySelector('#native-copy-name').value,values});};
 document.querySelector('#open-native-editor').onclick=async()=>{if(busy||!selected)return;setBusy(true);try{const result=await native.openNiagaraSystem(selected.asset,project);if(!result.ok)throw Error(result.error);status('Opening Unreal and the selected Niagara system. Use its preview for native effects; close the project before reading or saving here again.');}catch(error){status(error.message);}finally{setBusy(false);}};
 document.querySelector('#native-guide').onclick=()=>openDocumentation('nativeWorkspace');renderAssets();
})();
